package erratum

// Use opens a resource via opener, calls Frob(input) on it, and returns any
// resulting error.
//
// If the opener fails with a TransientError, Use keeps retrying until the
// resource is opened or a non-transient error is returned. Once the resource
// is opened successfully, its Close method is called exactly once no matter
// what happens afterwards.
//
// Frob may panic. If it panics with a FrobError, the resource's Defrob
// method is called with the FrobError's defrobTag (before the resource is
// closed) and the FrobError is returned. Any other error value panicked from
// Frob is returned as-is.
func Use(opener ResourceOpener, input string) error {
	var resource Resource
	for {
		var err error
		resource, err = opener()
		if err == nil {
			break
		}
		if _, ok := err.(TransientError); !ok {
			return err
		}
		// Transient error: the resource is temporarily unavailable, retry.
	}

	// The resource was opened successfully; make sure it is closed exactly
	// once no matter what happens below.
	defer resource.Close()

	var useErr error
	func() {
		defer func() {
			switch r := recover().(type) {
			case FrobError:
				resource.Defrob(r.defrobTag)
				useErr = r
			case error:
				useErr = r
			default:
				// Not an error value; let it keep propagating.
				panic(r)
			}
		}()
		resource.Frob(input)
	}()
	return useErr
}

